def ref(inp):
    t = list(map(int, inp.split()))
    n = t[0]
    # sort apples by time (T, X)
    pts = sorted((t[1 + 2 * i], t[2 + 2 * i]) for i in range(n))

    # a robot can collect apple b right after apple a (a earlier in time)
    # iff it can move from (T_a, X_a) to (T_b, X_b) at speed <= 1
    def reach(a, b):
        return b[0] - a[0] >= abs(b[1] - a[1])

    # exhaustive search: assign apples in time order to at most k robots,
    # each robot's consecutive collected apples must be reachable
    def feas(i, last, k):
        if i == n:
            return True
        for idx, j in enumerate(last):
            if reach(pts[j], pts[i]):
                new = last[:]
                new[idx] = i
                if feas(i + 1, new, k):
                    return True
        if len(last) < k:
            if feas(i + 1, last + [i], k):
                return True
        return False

    for k in range(1, n + 1):
        if feas(0, [], k):
            return str(k)
    return str(n)
